insert into public.projects (id, name, description, chapter_id, lead_id, category, status, start_date, end_date) values
  (1, 'Family Day volunteers', 'Family day for 100 families with games, auction and a picnic. Needs volunteers on the day.', 1, 1, 'Community', 'active', '2026-10-04', '2026-11-08'),
  (2, 'Founders Evening', 'Evening where local founders share their first-year stories with members and guests.', 1, 2, 'Business', 'active', '2026-10-14', '2026-11-08'),
  (3, 'Chapter growth', 'Ongoing push to bring 15 new members into Riga Go! this year.', 1, 3, 'Recruiting', 'active', '2026-08-25', '2026-12-23'),
  (4, 'Youth Mentoring', 'Members and senators mentor high-school students on careers and first jobs.', 2, 11, 'Education', 'active', '2026-09-09', '2026-12-08'),
  (5, 'Business Breakfast Series', 'Monthly breakfasts with a guest speaker. Sponsor covers food.', 2, 12, 'Business', 'active', '2026-09-24', '2027-02-21'),
  (6, 'Clean-up Day', 'City park clean-up with local schools and a partner company.', 3, 21, 'Environment', 'planning', '2026-11-03', '2026-12-03'),
  (7, 'Baltic Leadership Academy', 'Two-day training for new board members from all Baltic chapters.', 4, 27, 'Training', 'active', '2026-10-09', '2026-12-08'),
  (8, 'Nordic Hack Weekend', 'Weekend hackathon for civic tech ideas. Open to all Nordic Group chapters.', 5, 33, 'Tech', 'planning', '2026-11-13', '2026-12-23'),
  (9, 'Winter Charity Gala', 'Annual gala. Raised money for the children''s hospital.', 2, 13, 'Fundraising', 'completed', '2026-06-26', '2026-08-25');
